require "test_helper"

# ADR-0096, PRD §7: the codes of 3 900 schools, then the links of 20 000 classrooms, regenerated by the real jobs on
# PostgreSQL in under 60 s each, with a fixed number of SQL statements per batch. Skipped without PERF=1 (out of CI,
# played before acceptance). PERF_SCHOOLS and PERF_CLASSROOMS change the volumes; times and queries are logged.
class School::RegenerateCodesInBulkPerformanceTest < ActiveSupport::TestCase
  BUDGET_SECONDS = 60
  SCHOOLS = Integer(ENV.fetch("PERF_SCHOOLS", 3_900))
  CLASSROOMS = Integer(ENV.fetch("PERF_CLASSROOMS", 20_000))

  setup do
    skip "test de performance : lancez-le avec PERF=1" unless ENV["PERF"] == "1"
    @drena = create_drena(name: "Abidjan 1")
    @author = create_team_member(second_factor: false)
    @launch = Time.current
    insert_schools
  end

  def insert_schools
    created_at = @launch - 1.day
    codes = Entities::School::SchoolCode.generate_unique(count: SCHOOLS, taken: Set.new)
    rows = Array.new(SCHOOLS) do |index|
      { public_id: SecureRandom.base58(14), drena_id: @drena.id, name: "Lycée Moderne #{index + 1}", school_type: "public",
        cycle: "both", status: "active", school_code: codes[index], created_at:, updated_at: created_at }
    end
    rows.each_slice(1_000) { Orm::School.insert_all!(it) }
    analyze("schools")
  end

  # Les lignes du test ne sont jamais validées : sans ANALYZE, PostgreSQL croit les tables vides et croise chaque classe avec
  # chaque établissement (boucle imbriquée), quadratique. En production, l'autovacuum a analysé les tables bien avant.
  def analyze(table)
    ActiveRecord::Base.connection.execute("ANALYZE #{table}")
  end

  def insert_classrooms
    level = create_level
    year = current_school_year
    school_ids = Orm::School.ids
    created_at = @launch - 1.day
    # Un code distinct par classe (l'index écrit en base 31) : le défaut tiré par la base peut sortir deux fois le même
    # code sur 20 000 lignes d'un seul insert_all!, et l'index unique ferait échouer la préparation du test.
    symbols = Entities::Classroom::JoinCode::SYMBOLS
    rows = Array.new(CLASSROOMS) do |index|
      { public_id: SecureRandom.base58(14), school_id: school_ids[index % school_ids.size], level_id: level.id, school_year: year,
        name: "6e #{(index / school_ids.size) + 1}", created_at:, updated_at: created_at,
        join_code: Array.new(Entities::Classroom::JoinCode::LENGTH) { symbols[(index / (symbols.size**it)) % symbols.size] }.join }
    end
    rows.each_slice(2_000) { Orm::Classroom.insert_all!(it) }
    analyze("classrooms")
  end

  # → [secondes, requêtes SQL]
  def measure(job, kind, selection)
    report = create_import_report(kind:, checksum_sha256: nil, imported_by: @author, created_at: @launch,
                                  details: { "selection" => selection, "expected_count" => 0 })
    queries = 0
    counter = ->(*, payload) { queries += 1 unless payload[:name] == "SCHEMA" }
    started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
    ActiveSupport::Notifications.subscribed(counter, "sql.active_record") { job.perform_now(report.id) }
    elapsed = Process.clock_gettime(Process::CLOCK_MONOTONIC) - started
    assert_equal [ "completed", 0 ], report.reload.values_at(:status, :error_count)
    [ elapsed, queries, report.imported_count ]
  end

  test "the codes of every school, then the links of every classroom, each in under a minute" do
    elapsed, queries, changed = measure(School::RegenerateSchoolCodesJob, "school_codes", { "drena" => @drena.public_id })
    puts format("\n[PERF] codes de %d établissements : %d changés en %.1f s, %d requêtes SQL", SCHOOLS, changed, elapsed, queries)
    assert_equal SCHOOLS, changed
    assert_equal SCHOOLS, Orm::School.distinct.count(:school_code)
    assert_operator elapsed, :<, BUDGET_SECONDS

    insert_classrooms
    elapsed, queries, changed = measure(Classroom::RegenerateClassroomLinksJob, "classroom_links",
                                        { "drena" => @drena.public_id, "school_year" => current_school_year })
    puts format("[PERF] liens de %d classes : %d changés en %.1f s, %d requêtes SQL", CLASSROOMS, changed, elapsed, queries)
    assert_equal CLASSROOMS, changed
    assert_equal CLASSROOMS, Orm::Classroom.distinct.count(:link_token)
    assert_operator elapsed, :<, BUDGET_SECONDS
  end
end
